CREATE TRIGGER `trg_connection_create_conversation` AFTER INSERT ON `connections` FOR EACH ROW BEGIN

    IF NEW.status = 'accepted'
       OR NEW.status = 'connected' THEN

            connection_id,
            user_one_id,
            user_two_id,
            status
        )
        VALUES
        (
            NEW.id,
            NEW.user_id,
            NEW.connected_user_id,
            'active'
        )
        ON DUPLICATE KEY UPDATE
