DELIMITER $$
CREATE TRIGGER `trg_payment_paid_timestamp` BEFORE UPDATE ON `payments` FOR EACH ROW BEGIN

    IF
        NEW.status = 'paid'
        AND OLD.status <> 'paid'
        AND NEW.paid_at IS NULL
    THEN

        SET NEW.paid_at =
            CURRENT_TIMESTAMP;

    END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_payment_success_notification` AFTER UPDATE ON `payments` FOR EACH ROW BEGIN

    IF
        NEW.status = 'paid'
        AND OLD.status <> 'paid'
    THEN

            user_id,
            notification_type_id,
            title,
            message
        )

        SELECT
            NEW.user_id,
            nt.id,
            'Payment Successful',
            CONCAT(
                'Your payment ',
                NEW.payment_reference,
                ' was completed successfully.'
            )

        FROM notification_types nt

        WHERE nt.slug = 'payment_successful'

        LIMIT 1;

    END IF;

END
$$
